using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "VacuumsWingsOmenData", menuName = "Data/Battle/Omens System/Omen Data/Austra/VacuumsWingsOmenData")]
public class VacuumWingsOmenData : ModifyHeartWithEffectOmenData
{
	[Serializable]
	public class VacuumWingsValues
	{
		public int minimumDodgeAmount;

		public int decreaseDodgeAmount;

		public bool decreaseDoubleDodgeAmount;
	}

	[Header("ModifyHeartWithEffect Omen")]
	[SerializeField]
	private VacuumWingsValues vacuumWingsValues;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.VacuumWingsOmenActive = () => vacuumWingsValues;
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.VacuumWingsOmenActive = null;
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return GetStartOfBattleFormatedDescription() + "\n" + GetOmenRawLocalizedDescription() + "\n" + Smart.Format(base.localizationManager.GetLocalizedDodgeCantBeLower(), vacuumWingsValues.minimumDodgeAmount) + "\n" + GetModifyHeartsChantLocalizedDescription();
	}
}
